import { revalidateTag } from 'next/cache'
import { getCatalog } from '@/lib/catalog'
import { requestCatalogSync } from '@/lib/db'

export default async function ProductCatalogPage() {
  async function syncCatalog() {
    'use server'

    await requestCatalogSync()

    // Mark all catalog data as stale with stale-while-revalidate semantics:
    // admins keep getting the (briefly stale) cached catalog immediately,
    // and fresh data is recomputed in the background on the next visit to
    // any view tagged "products". No request blocks on the recompute.
    revalidateTag('products', 'max')
  }

  const { products, loadedAt } = await getCatalog()

  return (
    <main>
      <h1>Product Catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <p>Catalog data loaded at: {loadedAt}</p>

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

